import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../AuthContext';
import { departmentsApi } from '../services/api';
import './Login.css';
import Lottie from 'lottie-react';
import splashAnimation from '../Login.json';

function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [role, setRole] = useState('admin');
  const [departments, setDepartments] = useState([]);
  const [form, setForm] = useState({
    email: '',
    password: '',
    facultyId: '',
    facultyName: '',
    studentEmail: '',
    departmentId: '',
    sectionNumber: 1
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    // We can keep this if we want to target body specifically,
    // but the CSS handles .login-page wrapper well.
    document.body.classList.add('login-body');
    const fetchDepartments = async () => {
      try {
        const data = await departmentsApi.getAll();
        setDepartments(data);
      } catch (err) {
        console.error('Failed to fetch departments:', err);
      }
    };
    fetchDepartments();

    return () => {
      document.body.classList.remove('login-body');
    };
  }, []);

  useEffect(() => {
    if (departments.length > 0 && !form.departmentId) {
      setForm(prev => ({ ...prev, departmentId: departments[0]._id }));
    }
  }, [departments, form.departmentId]);

  const getAbbreviation = (name) => {
    if (!name) return '';
    // Common mappings or generic acronym generator
    const common = {
      'Computer Science and Engineering': 'CSE',
      'Electronics and Communication Engineering': 'ECE',
      'Electrical and Electronics Engineering': 'EEE',
      'Mechanical Engineering': 'MECH',
      'Civil Engineering': 'CIVIL',
      'Information Technology': 'IT',
      'Artificial Intelligence and Data Science': 'AI&DS'
    };
    if (common[name]) return common[name];

    return name.match(/\b([A-Z])/g)?.join('') || name.substring(0, 3).toUpperCase();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {
      let payload;
      if (role === 'admin') {
        payload = {
          role: 'admin',
          email: form.email,
          password: form.password
        };
      } else if (role === 'faculty') {
        payload = {
          role: 'faculty',
          facultyId: form.facultyId,
          name: form.facultyName
        };
      } else {
        payload = {
          role: 'student',
          email: form.studentEmail,
          departmentId: form.departmentId,
          sectionNumber: Number(form.sectionNumber) || 1
        };
      }
      const user = await login(payload);
      if (user.role === 'admin') {
        navigate('/');
      } else if (user.role === 'faculty') {
        navigate('/faculty-schedule');
      } else if (user.role === 'student') {
        navigate('/student-timetable');
      } else {
        navigate('/');
      }
    } catch (err) {
      setError(err.message || 'Login failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-container">

        {/* LEFT SIDE - ANIMATION */}
        <div className="login-left">
          <div className="dashboard-animation-wrap">
            <Lottie
              animationData={splashAnimation}
              loop
              className="login-lottie"
            />
          </div>
        </div>

        {/* RIGHT SIDE - FORM */}
        <div className="login-right">
          <div className="login-header">
            <h1>Welcome Back</h1>
            <p className="login-subtitle">Please enter your details to sign in.</p>
          </div>

          {error && (
            <div className="alert-error">
              <span>⚠️</span> {error}
            </div>
          )}

          <div className="form-group">
            <label>I am a</label>
            <select
              className="role-select"
              value={role}
              onChange={(e) => setRole(e.target.value)}
            >
              <option value="admin">Administrator</option>
              <option value="faculty">Faculty Member</option>
              <option value="student">Student</option>
            </select>
          </div>

          <form onSubmit={handleSubmit} className="login-form">
            {role === 'admin' && (
              <>
                <div className="form-group">
                  <label>Email Address</label>
                  <input
                    type="email"
                    required
                    value={form.email}
                    onChange={(e) => setForm((prev) => ({ ...prev, email: e.target.value }))}
                    placeholder="admin@example.com"
                  />
                </div>
                <div className="form-group">
                  <label>Password</label>
                  <input
                    type="password"
                    required
                    value={form.password}
                    onChange={(e) => setForm((prev) => ({ ...prev, password: e.target.value }))}
                    placeholder="••••••••"
                  />
                </div>
              </>
            )}

            {role === 'faculty' && (
              <>
                <div className="form-group">
                  <label>Faculty ID</label>
                  <input
                    required
                    value={form.facultyId}
                    onChange={(e) => setForm((prev) => ({ ...prev, facultyId: e.target.value }))}
                    placeholder="e.g. CSE001"
                  />
                </div>
                <div className="form-group">
                  <label>Full Name</label>
                  <input
                    required
                    value={form.facultyName}
                    onChange={(e) => setForm((prev) => ({ ...prev, facultyName: e.target.value }))}
                    placeholder="Exact name as registered"
                  />
                </div>
              </>
            )}

            {role === 'student' && (
              <>
                <div className="form-group">
                  <label>Email Address</label>
                  <input
                    type="email"
                    required
                    value={form.studentEmail}
                    onChange={(e) => setForm((prev) => ({ ...prev, studentEmail: e.target.value }))}
                    placeholder="student@example.com"
                  />
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label>Department</label>
                    <select
                      required
                      value={form.departmentId}
                      onChange={(e) => setForm((prev) => ({ ...prev, departmentId: e.target.value }))}
                    >
                      <option value="">Select Dept</option>
                      {Array.isArray(departments) && departments.map((dept) => (
                        <option key={dept._id} value={dept._id}>
                          {getAbbreviation(dept.name)}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="form-group">
                    <label>Section</label>
                    <input
                      type="number"
                      min={1}
                      max={20}
                      value={form.sectionNumber}
                      onChange={(e) => setForm((prev) => ({ ...prev, sectionNumber: e.target.value }))}
                    />
                  </div>
                </div>
              </>
            )}

            <button type="submit" className="btn-primary" disabled={loading}>
              {loading ? 'Signing in...' : 'Sign In'}
            </button>

            <div className="divider">
              <span>Or continue with</span>
            </div>
            <button
              type="button"
              className="google-btn"
              onClick={() => console.log('Google Sign In')}
            >
              <img
                src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg"
                alt="google"
                className="google-icon"
              />
              Google
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

export default Login;
